structureCode.vanilla:
const grupo = createRadioGroup({
  name: 'pagamento',
  defaultValue: 'cartao',
  orientation: 'vertical',
  onValueChange: (value) => setValue(value),
  items: [
    { value: 'cartao', label: 'Cartão de crédito' },
    { value: 'pix', label: 'Pix' },
  ],
});
// Cada item já vem com o próprio rótulo associado; o grupo é um
// fieldset com role="radiogroup".
grupo.setAttribute('aria-label', 'Forma de pagamento');

extensibilityCode.react:
// Integração com FormField (React Hook Form)
<FormField
  control={form.control}
  name="payment"
  render={({ field }) => (
    <FormItem className="space-y-3">
      <FormLabel>Forma de pagamento</FormLabel>
      <FormControl>
        <RadioGroup
          value={field.value}
          onValueChange={field.onChange}
        >
          {options.map((opt) => (
            <div key={opt.value} className="flex items-center space-x-2">
              <RadioGroupItem value={opt.value} id={opt.value} />
              <Label htmlFor={opt.value}>{opt.label}</Label>
            </div>
          ))}
        </RadioGroup>
      </FormControl>
      <FormMessage />
    </FormItem>
  )}
/>

extensibilityCode.vanilla:
// Integração com formulário nativo: cada item mantém um input[type="radio"]
// com o mesmo `name`, então o valor chega ao FormData sem fiação extra.
const grupo = createRadioGroup({ name: 'payment', items: opcoes });
formulario.appendChild(grupo);

formulario.addEventListener('submit', (evento) => {
  evento.preventDefault();
  enviar(new FormData(formulario).get('payment'));
});

customizationCode.web:
/* Rádio maior num formulário denso */
.pagamento .nds-radio-item {
  width: 1.25rem;
  height: 1.25rem;
}

/* Outra cor para o item escolhido — borda e bolinha saem do mesmo token */
.pagamento .nds-radio-item[aria-checked="true"] {
  border-color: hsl(var(--chart-2));
}

.pagamento .nds-radio-item[aria-checked="true"] .nds-radio-indicator > svg,
.pagamento .nds-radio-item[aria-checked="true"] .nds-radio-indicator:empty::after {
  fill: hsl(var(--chart-2));
  background-color: hsl(var(--chart-2));
}

